'use strict';

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function searchNotes(notes, phrase) {
  if (!Array.isArray(notes) || typeof phrase !== 'string') throw new TypeError('invalid arguments');
  for (const note of notes) {
    if (!isPlainObject(note) || typeof note.title !== 'string' || typeof note.body !== 'string' ||
        ('archived' in note && typeof note.archived !== 'boolean')) {
      throw new TypeError('malformed note');
    }
  }

  const needle = phrase.trim().toLowerCase();
  if (needle === '') return [];
  return notes
    .filter((note) => note.title.toLowerCase().includes(needle) || note.body.toLowerCase().includes(needle))
    .map((note) => ({ ...note }));
}

function findTag(tags, name) {
  if (!Array.isArray(tags) || typeof name !== 'string') throw new TypeError('invalid arguments');
  for (const tag of tags) {
    if (!isPlainObject(tag) || typeof tag.name !== 'string' || typeof tag.description !== 'string') {
      throw new TypeError('malformed tag');
    }
  }

  const needle = name.trim().toLowerCase();
  if (needle === '') return null;
  const match = tags.find((tag) => tag.name.trim().toLowerCase() === needle);
  return match ? { ...match } : null;
}

module.exports = { searchNotes, findTag };

