'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['findTag', 'searchNotes']);
const { searchNotes, findTag } = api;

const notes = [
  { title: 'Project Alpha', body: 'First body', extra: { opaque: true } },
  { title: 'Other', body: 'ALPHA appears here', archived: false },
  { title: 'Alpha archived', body: 'hidden', archived: true },
  { title: 'Unrelated', body: 'nothing' }
];
const before = notes.map((note) => ({ ...note }));
const matches = searchNotes(notes, '  aLpHa  ');
assert.deepStrictEqual(matches, [notes[0], notes[1]]);
assert.notStrictEqual(matches[0], notes[0]);
assert.notStrictEqual(matches[1], notes[1]);
assert.strictEqual(matches[0].extra, notes[0].extra);
matches[0].title = 'Changed';
assert.equal(notes[0].title, 'Project Alpha');
assert.deepStrictEqual(notes, before);
assert.deepStrictEqual(searchNotes(notes, '   '), []);
assert.deepStrictEqual(searchNotes([], 'anything'), []);

const tags = [
  { name: ' JavaScript ', description: 'language', extra: 1 },
  { name: 'javascript', description: 'second' },
  { name: 'Node', description: 'runtime' }
];
const found = findTag(tags, ' JAVASCRIPT ');
assert.deepStrictEqual(found, tags[0]);
assert.notStrictEqual(found, tags[0]);
found.description = 'changed';
assert.equal(tags[0].description, 'language');
assert.equal(findTag(tags, 'missing'), null);
assert.equal(findTag(tags, '   '), null);
assert.equal(findTag([], 'node'), null);

assert.throws(() => searchNotes(null, 'x'), TypeError);
assert.throws(() => searchNotes([], 1), TypeError);
assert.throws(() => searchNotes([{ title: 'ok', body: 2 }], 'x'), TypeError);
assert.throws(() => searchNotes([{ title: 'ok', body: 'ok', archived: 'no' }], ''), TypeError);
assert.throws(() => searchNotes([null], '   '), TypeError);
assert.throws(() => findTag({}, 'x'), TypeError);
assert.throws(() => findTag([], null), TypeError);
assert.throws(() => findTag([{ name: 'x', description: 3 }], 'x'), TypeError);
assert.throws(() => findTag([null], ''), TypeError);

